package api

import (
	"io"
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/rbac-admin-api/internal/decision"
	"github.com/luwa07832/rbac-admin-api/internal/store"
)

const maxDecisionBodyBytes = 1 << 20

// NewRouter wires the public HTTP surface. The service contract in README.md
// describes the error shape every entry must keep.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	router.POST("/authorize", func(c *gin.Context) {
		c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, maxDecisionBodyBytes)
		body, err := io.ReadAll(c.Request.Body)
		if err != nil {
			writeDecisionError(c, &decision.DecisionError{
				Code:    decision.CodeInvalidRequest,
				Message: "request body is missing or too large",
			})
			return
		}
		result, decisionErr := decision.Decide(body)
		if decisionErr != nil {
			writeDecisionError(c, decisionErr)
			return
		}
		c.JSON(http.StatusOK, gin.H{"decision": result})
	})

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

func writeDecisionError(c *gin.Context, decisionErr *decision.DecisionError) {
	status := http.StatusBadRequest
	switch decisionErr.Code {
	case decision.CodeSubjectNotFound, decision.CodeResourceNotFound, decision.CodeOperationNotFound:
		status = http.StatusNotFound
	}
	c.JSON(status, gin.H{"error": gin.H{"code": decisionErr.Code, "message": decisionErr.Message}})
}
package api

import (
	"bytes"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"testing"

	"github.com/luwa07832/rbac-admin-api/internal/store"
)

const baseBody = `{
  "subject": "user-1",
  "resource": "tenant-a/doc-1",
  "operation": "read",
  "subjects": [{"id": "user-1"}],
  "resources": [{"id": "tenant-a/doc-1"}],
  "operations": [{"id": "read"}],
  "roles": [{"id": "viewer", "permissions": ["doc-read"]}],
  "permissions": [{"id": "doc-read", "operations": ["read"]}],
  "bindings": [{"subject": "user-1", "role": "viewer"}],
  "grants": [
    {"subject": "user-1", "role": "viewer", "scope": "tenant-a/*", "effect": "allow"},
    {"subject": "user-1", "permission": "doc-read", "scope": "tenant-a/doc-1", "effect": "allow"}
  ]
}`

func newAuthorizeRouter(t *testing.T) http.Handler {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return NewRouter(st)
}

func postAuthorize(t *testing.T, router http.Handler, body string) *httptest.ResponseRecorder {
	t.Helper()
	recorder := httptest.NewRecorder()
	request := httptest.NewRequest(http.MethodPost, "/authorize", bytes.NewBufferString(body))
	request.Header.Set("Content-Type", "application/json")
	router.ServeHTTP(recorder, request)
	return recorder
}

func TestAuthorizeReturnsExplainedDecision(t *testing.T) {
	recorder := postAuthorize(t, newAuthorizeRouter(t), baseBody)
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
	}
	want := `{"decision":{"allowed":true,"role":null,"permission":"doc-read","scope":"tenant-a/doc-1","reason":"authorized"}}`
	if recorder.Body.String() != want {
		t.Fatalf("body = %s, want %s", recorder.Body.String(), want)
	}
}

func TestAuthorizeUnknownSubjectUses404Shape(t *testing.T) {
	body := `{"subject":"ghost","resource":"tenant-a/doc-1","operation":"read","resources":[{"id":"tenant-a/doc-1"}],"operations":[{"id":"read"}]}`
	recorder := postAuthorize(t, newAuthorizeRouter(t), body)
	if recorder.Code != http.StatusNotFound {
		t.Fatalf("status = %d, want 404", recorder.Code)
	}
	if got := recorder.Body.String(); got != `{"error":{"code":"subject_not_found","message":"subject does not exist"}}` {
		t.Fatalf("body = %s", got)
	}
}

func TestAuthorizeInvalidRequestUses400Shape(t *testing.T) {
	for _, body := range []string{"", "nope", `{"subject":"s"}`, `{"subject":["s"]}`} {
		recorder := postAuthorize(t, newAuthorizeRouter(t), body)
		if recorder.Code != http.StatusBadRequest {
			t.Fatalf("status = %d for body %q, want 400", recorder.Code, body)
		}
	}
}

func TestAuthorizeIsDeterministic(t *testing.T) {
	router := newAuthorizeRouter(t)
	first := postAuthorize(t, router, baseBody)
	second := postAuthorize(t, router, baseBody)
	if first.Body.String() != second.Body.String() {
		t.Fatalf("bodies drifted: %s vs %s", first.Body.String(), second.Body.String())
	}
}

