// Package decision implements stateless, explainable authorization decisions.
//
// A request carries a read-only snapshot of the current authorization records
// (catalogs and grants) together with one subject/resource/operation triple.
// The evaluator never mutates that snapshot and never persists anything, so the
// same request body yields an identical decision as long as records are
// unchanged.
package decision

import (
	"encoding/json"
	"reflect"
	"sort"
	"strconv"
	"strings"
)

// Stable codes returned inside a decision or an error response.
const (
	ReasonAuthorized     = "authorized"
	ReasonDenied         = "explicit_deny"
	ReasonNoMatchingRole = "no_matching_role"
	ReasonScopeMismatch  = "scope_mismatch"

	CodeInvalidRequest    = "request_invalid"
	CodeSubjectNotFound   = "subject_not_found"
	CodeResourceNotFound  = "resource_not_found"
	CodeOperationNotFound = "operation_not_found"
)

// Request is the public decision payload. The slices carry a snapshot of the
// existing records; evaluation never creates, updates or deletes them.
type Request struct {
	Subject     string    `json:"subject"`
	Resource    string    `json:"resource"`
	Operation   string    `json:"operation"`
	Subjects    []Catalog `json:"subjects"`
	Resources   []Catalog `json:"resources"`
	Operations  []Catalog `json:"operations"`
	Roles       []RoleDef `json:"roles"`
	Permissions []PermDef `json:"permissions"`
	Bindings    []Binding `json:"bindings"`
	Grants      []Grant   `json:"grants"`
}

// Catalog identifies one existing subject, resource or operation.
type Catalog struct {
	ID string `json:"id"`
}

// RoleDef records a role, the permission points it includes and the roles it
// inherits permission points from.
type RoleDef struct {
	ID          string   `json:"id"`
	Parents     []string `json:"parents"`
	Permissions []string `json:"permissions"`
}

// PermDef records a permission point and the operations it directly covers.
type PermDef struct {
	ID         string   `json:"id"`
	Operations []string `json:"operations"`
}

// Binding attaches a role to a subject.
type Binding struct {
	Subject string `json:"subject"`
	Role    string `json:"role"`
}

// Grant is one direct or role-derived authorization record constrained by a
// scope. Exactly one of Role and Permission is set: a role grant authorizes
// through the subject's bindings and the role's permission points (including
// inherited ones); a permission grant authorizes the named subject directly.
// Both forms produce the same decision shape.
type Grant struct {
	Subject    string `json:"subject"`
	Role       string `json:"role,omitempty"`
	Permission string `json:"permission,omitempty"`
	Scope      string `json:"scope"`
	Effect     string `json:"effect"`
}

// Result is the deterministic conclusion for one subject/resource/operation
// triple. Role, Permission and Scope are nil when they do not apply, so the
// JSON shape of every outcome stays stable.
type Result struct {
	Allowed    bool    `json:"allowed"`
	Role       *string `json:"role"`
	Permission *string `json:"permission"`
	Scope      *string `json:"scope"`
	Reason     string  `json:"reason"`
}

// DecisionError is the structured failure shared by every abnormal outcome.
type DecisionError struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

func (e *DecisionError) Error() string { return e.Code + ": " + e.Message }

var requestType = reflect.TypeOf(Request{})

// Decode parses one request body, rejecting empty bodies, unknown fields,
// trailing JSON values and every type that does not match the interface.
func Decode(body []byte) (*Request, *DecisionError) {
	if len(strings.TrimSpace(string(body))) == 0 {
		return nil, invalidRequest("request body is empty")
	}
	var raw interface{}
	if err := json.Unmarshal(body, &raw); err != nil {
		return nil, invalidRequest("request body is not a valid decision request: syntax or field name is invalid")
	}
	if path := findUnknownFields(raw, requestType, ""); path != "" {
		return nil, invalidRequest("request body contains unknown field " + path)
	}
	var req Request
	decoder := json.NewDecoder(strings.NewReader(string(body)))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&req); err != nil {
		if typeError, ok := err.(*json.UnmarshalTypeError); ok {
			return nil, invalidRequest("request body is not a valid decision request: field " + typeError.Field + " has the wrong type")
		}
		return nil, invalidRequest("request body is not a valid decision request: syntax or field name is invalid")
	}
	if decoder.More() {
		return nil, invalidRequest("request body contains more than one JSON value")
	}
	return &req, nil
}

// findUnknownFields walks raw JSON using the JSON tags of the request structs
// and returns the first stable path such as subjects[0].id. A null or scalar
// where an object or array is expected is left for the typed decode to report
// as a type mismatch.
func findUnknownFields(raw interface{}, typ reflect.Type, path string) string {
	for typ.Kind() == reflect.Ptr {
		typ = typ.Elem()
	}
	switch typ.Kind() {
	case reflect.Struct:
		object, ok := raw.(map[string]interface{})
		if !ok {
			return ""
		}
		known := map[string]reflect.Type{}
		for i := 0; i < typ.NumField(); i++ {
			field := typ.Field(i)
			tag := strings.Split(field.Tag.Get("json"), ",")[0]
			if tag != "" && tag != "-" {
				known[tag] = field.Type
			}
		}
		keys := make([]string, 0, len(object))
		for key := range object {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			childPath := key
			if path != "" {
				childPath = path + "." + key
			}
			childType, exists := known[key]
			if !exists {
				return childPath
			}
			if nested := findUnknownFields(object[key], childType, childPath); nested != "" {
				return nested
			}
		}
	case reflect.Slice:
		items, ok := raw.([]interface{})
		if !ok {
			return ""
		}
		for i, item := range items {
			childPath := path + "[" + strconv.Itoa(i) + "]"
			if nested := findUnknownFields(item, typ.Elem(), childPath); nested != "" {
				return nested
			}
		}
	}
	return ""
}

// Decide decodes and evaluates one request body.
func Decide(body []byte) (*Result, *DecisionError) {
	req, err := Decode(body)
	if err != nil {
		return nil, err
	}
	return Evaluate(req)
}

// Evaluate applies the existing authorization semantics to one triple.
func Evaluate(req *Request) (*Result, *DecisionError) {
	index, err := validate(req)
	if err != nil {
		return nil, err
	}

	candidates, err := buildCandidates(req, index)
	if err != nil {
		return nil, err
	}
	if len(candidates) == 0 {
		return &Result{
			Allowed:    false,
			Role:       nil,
			Permission: nil,
			Scope:      nil,
			Reason:     ReasonNoMatchingRole,
		}, nil
	}

	sortCandidates(candidates)

	for _, candidate := range candidates {
		if !candidate.scope.matches(req.Resource) {
			continue
		}
		scope := candidate.scope.text
		result := &Result{
			Role:       nullableID(candidate.role),
			Permission: nullableID(candidate.permission),
			Scope:      &scope,
		}
		if candidate.effect == effectDeny {
			result.Allowed = false
			result.Reason = ReasonDenied
		} else {
			result.Allowed = true
			result.Reason = ReasonAuthorized
		}
		return result, nil
	}

	best := candidates[0]
	return &Result{
		Allowed:    false,
		Role:       nullableID(best.role),
		Permission: nullableID(best.permission),
		Scope:      nil,
		Reason:     ReasonScopeMismatch,
	}, nil
}

type candidate struct {
	role       string
	permission string
	direct     bool
	scope      scopeRef
	effect     string
}

func buildCandidates(req *Request, index *validatedIndex) ([]candidate, *DecisionError) {
	reachable := reachableRoles(req, index.roles)

	var candidates []candidate
	for _, grant := range req.Grants {
		if grant.Subject != req.Subject {
			continue
		}
		scope := index.grantScopes[grant.identity()]
		if grant.Permission != "" {
			permission := index.permissions[grant.Permission]
			if !permissionCovers(permission, req.Operation) {
				continue
			}
			candidates = append(candidates, candidate{
				permission: grant.Permission,
				direct:     true,
				scope:      scope,
				effect:     grant.Effect,
			})
			continue
		}
		if !reachable[grant.Role] {
			continue
		}
		for _, permission := range permissionsUnderRole(index.roles[grant.Role], index.roles) {
			if !permissionCovers(index.permissions[permission], req.Operation) {
				continue
			}
			candidates = append(candidates, candidate{
				role:       grant.Role,
				permission: permission,
				direct:     false,
				scope:      scope,
				effect:     grant.Effect,
			})
		}
	}

	for i := 0; i < len(candidates); i++ {
		for j := i + 1; j < len(candidates); j++ {
			if candidates[i].effect != candidates[j].effect &&
				candidates[i].permission == candidates[j].permission &&
				scopesOverlap(candidates[i].scope, candidates[j].scope) {
				return nil, invalidRequest("allow and deny grants conflict on the same permission and overlapping scope")
			}
		}
	}
	return candidates, nil
}

// sortCandidates imposes the single deterministic explanation order: the most
// specific matching scope wins; a direct permission grant outranks a
// role-derived grant; permission and role identifiers then break ties.
