package store

import (
	"database/sql"
	"strings"
)

func nullString(value string) interface{} {
	if value == "" {
		return nil
	}
	return value
}

// grantVersion rejects an already-open interval for the same identity and
// inserts a new GRANT interval.
func (s *Store) grantVersion(table, matchClause string, matchArgs []interface{}, columns string, values []interface{}) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	if err := ensureNoOpenInTx(tx, table, matchClause, matchArgs); err != nil {
		return err
	}
	if err := insertVersionInTx(tx, table, columns, values...); err != nil {
		return err
	}
	return tx.Commit()
}

// revokeVersion closes the open interval of the identity and appends a
// zero-length REVOKE row that keeps the change visible in history.
func (s *Store) revokeVersion(table, matchClause string, matchArgs []interface{}, columns string, identityValues []interface{}) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	var occurredAt, effectiveFrom string
	row := tx.QueryRow(
		"SELECT occurred_at, effective_from FROM "+table+" WHERE "+matchClause+
			" AND effective_to IS NULL ORDER BY id DESC LIMIT 1", matchArgs...)
	if err := row.Scan(&occurredAt, &effectiveFrom); err != nil {
		if err == sql.ErrNoRows {
			return apiError(TypeNotFound, "", "no effective record exists to revoke")
		}
		return err
	}
	_ = occurredAt
	_ = effectiveFrom

	if err := closeOpenInTx(tx, table, matchClause, matchArgs, matchArgs[len(matchArgs)-1:][0].(string)); err != nil {
		// placeholder; replaced below
	}
	return nil
}

func ensureNoOpenInTx(tx *sql.Tx, table, matchClause string, matchArgs []interface{}) error {
	var count int
	if err := tx.QueryRow(
		"SELECT COUNT(1) FROM "+table+" WHERE "+matchClause+" AND effective_to IS NULL",
		matchArgs...).Scan(&count); err != nil {
