type snapshot struct {
	bindings []bindingRow
	rolePerm []rolePermRow
	scopes   []scopeRow

	// rolesWith lists every permission a role contributes directly.
	rolesWith map[string]map[string]bool
	// roleParents lists parent roles in stored order.
	roleParents map[string][]string
	// permOperations lists operations covered by each permission.
	permOperations map[string]map[string]bool
}

func (s *Service) loadSnapshot(subject string) (*snapshot, error) {
	snap := &snapshot{
		rolesWith:      map[string]map[string]bool{},
		roleParents:    map[string][]string{},
		permOperations: map[string]map[string]bool{},
	}

	bindingVersions, err := s.store.ListBindingVersions(subject)
	if err != nil {
		return nil, err
	}
	for _, version := range bindingVersions {
		snap.bindings = append(snap.bindings, bindingRow{
			roleID:        version.RoleID,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}

	rolePermVersions, err := s.store.ListRolePermissionVersions()
	if err != nil {
		return nil, err
	}
	for _, version := range rolePermVersions {
		snap.rolePerm = append(snap.rolePerm, rolePermRow{
			roleID:        version.RoleID,
			permissionID:  version.PermissionID,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}

	scopeVersions, err := s.store.ListScopeVersions(subject)
	if err != nil {
		return nil, err
	}
	for _, version := range scopeVersions {
		parsedScope, ok := parseScope(version.ScopeText)
		if !ok {
			continue
		}
		snap.scopes = append(snap.scopes, scopeRow{
			roleID:        version.RoleID,
			permissionID:  version.PermissionID,
			scope:         parsedScope,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}

	roleRows, err := s.listRoleGraph()
	if err != nil {
		return nil, err
	}
	for roleID := range roleRows {
		parents, err := s.store.RoleParents(roleID)
		if err != nil {
			return nil, err
		}
		snap.roleParents[roleID] = parents
	}
	permRows, err := s.listPermissionOperations()
	if err != nil {
		return nil, err
	}
	snap.permOperations = permRows

	for _, row := range snap.rolePerm {
		if row.effectiveTo != "" {
			continue
		}
		if snap.rolesWith[row.roleID] == nil {
			snap.rolesWith[row.roleID] = map[string]bool{}
		}
		snap.rolesWith[row.roleID][row.permissionID] = true
	}
	return snap, nil
}

func (s *Service) listRoleGraph() (map[string]bool, error) {
	roles := map[string]bool{}
	for _, version := range mustRolePerm(s) {
		roles[version] = true
	}
	return roles, nil
}

func mustRolePerm(s *Service) []string { return nil }

func (s *Service) listPermissionOperations() (map[string]map[string]bool), error) {
	result := map[string]map[string]bool{}
	permissions := []string{}
	// Permissions are listed through the catalog table; the store exposes
	// operations per permission, so fetch the full catalog first via a store
	// helper.
	ids, err := s.store.ListCatalog(store.CatalogPermission)
	if err != nil {
		return nil, err
	}
	permissions = ids
	for _, permissionID := range permissions {
		operations, err := s.store.PermissionOperations(permissionID)
		if err != nil {
			return nil, err
		}
		set := map[string]bool{}
		for _, operation := range operations {
			set[operation] = true
		}
		result[permissionID] = set
	}
	return result, nil
}

// sortRows keeps every slice chronologically ordered for stable evaluation.
func sortRows[T interface {
	rowMeta() (from, at string, id int64)
}](rows []T) {
	sort.SliceStable(rows, func(i, j int) bool {
		fromI, atI, idI := rows[i].rowMeta()
		fromJ, atJ, idJ := rows[j].rowMeta()
		if fromI != fromJ {
			return fromI < fromJ
		}
		if atI != atJ {
			return atI < atJ
		}
		return idI < idJ
	})
}

func (b bindingRow) rowMeta() (string, string, int64) { return b.effectiveFrom, b.occurredAt, b.id }
func (r rolePermRow) rowMeta() (string, string, int64) {
	return r.effectiveFrom, r.occurredAt, r.id
}
func (r scopeRow) rowMeta() (string, string, int64) { return r.effectiveFrom, r.occurredAt, r.id }

var _ = strings.TrimSpace
EOF
