	Subject     string `json:"subject"`
	Resource    string `json:"resource"`
	Operation   string `json:"operation"`
	EffectiveAt string `json:"effectiveAt,omitempty"`
}

// Match identifies the role-derived or direct authorization that explains a
// granted decision. Role is empty for direct permission grants.
type Match struct {
	Role       string
	Permission string
	Scope      string
}

// Decision is the service-level conclusion.
type Decision struct {
	Granted bool
	Reason  string
	Match   *Match
}

// Decide evaluates the triple at effectiveAt, defaulting to the current time.
func (s *Service) Decide(in DecisionInput) (*Decision, *Failure) {
	if fail := requireIdentifiers(in.Subject, in.Resource, in.Operation); fail != nil {
		return nil, fail
	}
	if fail := s.checkTriple(in.Subject, in.Resource, in.Operation); fail != nil {
		return nil, fail
	}
	at := time.Now().UTC()
	if in.EffectiveAt != "" {
		parsed, fail := ParseTime(in.EffectiveAt)
		if fail != nil {
			return nil, fail
		}
		at = parsed
	}

	snap, err := s.loadSnapshot(in.Subject)
	if err != nil {
		return nil, failure(TypeInvalidRequest, "", "could not evaluate authorization")
	}
	return evaluate(snap, in.Subject, in.Resource, in.Operation, at), nil
}

// candidate is one authorization path that structurally covers the triple
// (ignoring time or scope, depending on the set it belongs to).
type candidate struct {
	role       string
	permission string
	scope      scopeRef
	from       string
	to         string
}

func candidateLess(a, b candidate) bool {
	if cmp := compareScope(a.scope, b.scope); cmp != 0 {
		return cmp < 0
	}
	if a.permission != b.permission {
		return a.permission < b.permission
	}
	return a.role < b.role
}

// reachableRoles expands the statically inherited roles reachable from the
// given entry roles.
func reachableRoles(entries map[string]bool, parents map[string][]string) map[string]bool {
	reachable := map[string]bool{}
	queue := make([]string, 0, len(entries))
	for role := range entries {
		reachable[role] = true
		queue = append(queue, role)
	}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		for _, parent := range parents[current] {
			if !reachable[parent] {
				reachable[parent] = true
				queue = append(queue, parent)
			}
		}
	}
	return reachable
}

// effectiveRoles returns roles reachable through bindings active at at.
func effectiveRoles(snap *snapshot, at string) map[string]bool {
	entries := map[string]bool{}
	for _, row := range snap.bindings {
		if rowActive(row.effectiveFrom, row.effectiveTo, at) {
			entries[row.roleID] = true
		}
	}
	return reachableRoles(entries, snap.roleParents)
}

// rolesEver returns roles reachable through any binding interval that exists
// (regardless of whether it is active at at).
func rolesEver(snap *snapshot) map[string]bool {
	entries := map[string]bool{}
	for _, row := range snap.bindings {
		entries[row.roleID] = true
	}
	return reachableRoles(entries, snap.roleParents)
}

// rolePermissionsActiveAt lists (role, permission) pairs whose interval is
// active at at.
func rolePermissionsActiveAt(snap *snapshot, at string) map[[2]string]bool {
	result := map[[2]string]bool{}
	for _, row := range snap.rolePerm {
		if rowActive(row.effectiveFrom, row.effectiveTo, at) {
			result[[2]string{row.roleID, row.permissionID}] = true
		}
	}
	return result
}

// rolePermissionsEver lists every (role, permission) pair with an interval.
func rolePermissionsEver(snap *snapshot) map[[2]string]bool {
	result := map[[2]string]bool{}
	for _, row := range snap.rolePerm {
		result[[2]string{row.roleID, row.permissionID}] = true
	}
	return result
}

// permissionCovers reports whether the static permission definition covers op.
func permissionCovers(snap *snapshot, permissionID, operation string) bool {
	return snap.permOperations[permissionID][operation]
}

// buildCandidates collects all structural candidates (scope rows matching the
// resource) whose permission covers the operation. roleFilter constrains
// role-derived rows; direct rows are always eligible. Timing of the scope
// interval is not applied here.
func buildCandidates(snap *snapshot, roles map[string]bool, resource, operation string) []candidate {
	activeRolePerm := rolePermissionsEver(snap)
	var candidates []candidate
	for _, row := range snap.scopes {
		if !row.scope.matches(resource) {
			continue
		}
		if row.permissionID != "" {
			if permissionCovers(snap, row.permissionID, operation) {
				candidates = append(candidates, candidate{
					permission: row.permissionID,
					scope:      row.scope,
					from:       row.effectiveFrom,
					to:         row.effectiveTo,
				})
			}
			continue
		}
		if !roles[row.roleID] {
			continue
		}
		if !activeRolePerm[[2]string{row.roleID, ""}] && !activeRolePerm[[2]string{row.roleID, rolePermKey(snap, row.roleID, operation)}] {
		}
		for pair := range activeRolePerm {
			if pair[0] == row.roleID && pair[1] != "" && permissionCovers(snap, pair[1], operation) {
				candidates = append(candidates, candidate{
					role:       row.roleID,
					permission: pair[1],
					scope:      row.scope,
					from:       row.effectiveFrom,
					to:         row.effectiveTo,
				})
			}
		}
	}
	return candidates
}

// rolePermKey is unused but keeps the candidate loop self-documenting; the
// actual matching iterates active pairs.
func rolePermKey(snap *snapshot, role, operation string) string { return "" }

var _ = store.EventGrant

// evaluate implements the published denial precedence:
//
//	layer 1: the subject never had / does not currently have a reachable role;
//	layer 2: no role ever / currently carries a covering permission, or no
//	         direct permission grant ever / currently exists;
//	layer 3: the matching scope pattern is never active or never matches.
func evaluate(snap *snapshot, subject, resource, operation string, at time.Time) *Decision {
	atText := FormatTime(at)

	rolesNow := effectiveRoles(snap, atText)
	rolesPast := rolesEver(snap)
	rolePermNow := rolePermissionsActiveAt(snap, atText)
	rolePermAll := rolePermissionsEver(snap)

	// Direct permission scopes ignore role bindings entirely.
	directNow := false
	directEver := false
	for _, row := range snap.scopes {
		if row.permissionID == "" || !permissionCovers(snap, row.permissionID, operation) || !row.scope.matches(resource) {
			continue
		}
		directEver = true
		if rowActive(row.effectiveFrom, row.effectiveTo, atText) {
			directNow = true
		}
	}

	if directNow {
		return bestDirect(snap, resource, operation, atText)
	}

	// Layer 1: without any reachable role (direct grants bypass this layer).
	if len(rolesNow) == 0 {
		if len(rolesPast) == 0 && !directEver {
			return denied(ReasonNoRoleBinding)
		}
		if len(rolesPast) > 0 {
			return denied(ReasonNotEffective)
		}
	}

	// Layer 2 for role-derived grants.
	roleCoversNow := false
	roleCoversEver := false
	for role := range rolesNow {
		for pair := range rolePermNow {
			if pair[0] == role && permissionCovers(snap, pair[1], operation) {
				roleCoversNow = true
			}
		}
	}
	for role := range rolesPast {
		for pair := range rolePermAll {
			if pair[0] == role && permissionCovers(snap, pair[1], operation) {
				roleCoversEver = true
			}
		}
	}
	if !roleCoversNow {
		if roleCoversEver {
			return denied(ReasonNotEffective)
		}
		if !directEver {
			return denied(ReasonNoPermissionBinding)
		}
	}

	// Layer 2 for direct grants: grant exists historically but not now.
	if directEver && !directNow {
		return denied(ReasonNotEffective)
	}

	// Layer 3: role-derived scope rows for covering permissions.
	var scopeCandidates []candidate
	for role := range rolesNow {
		for pair := range rolePermNow {
			if pair[0] != role || !permissionCovers(snap, pair[1], operation) {
				continue
			}
			for _, row := range snap.scopes {
				if row.roleID != role {
					continue
				}
				if row.scope.matches(resource) {
					scopeCandidates = append(scopeCandidates, candidate{
						role:       role,
						permission: pair[1],
						scope:      row.scope,
						from:       row.effectiveFrom,
						to:         row.effectiveTo,
					})
				}
			}
		}
	}

	active := false
	everMatched := false
	for _, candidate := range scopeCandidates {
		everMatched = true
		if rowActive(candidate.from, candidate.to, atText) {
			active = true
		}
	}
	if !everMatched {
		if directEver {
			return denied(ReasonNotEffective)
		}
		return denied(ReasonOutOfScope)
	}
	if !active {
		return denied(ReasonNotEffective)
	}

	sort.SliceStable(scopeCandidates, func(i, j int) bool { return candidateLess(scopeCandidates[i], scopeCandidates[j]) })
	for _, candidate := range scopeCandidates {
		if rowActive(candidate.from, candidate.to, atText) {
			return granted(candidate)
		}
	}
	return denied(ReasonNotEffective)
}

func bestDirect(snap *snapshot, resource, operation, at string) *Decision {
	var candidates []candidate
	for _, row := range snap.scopes {
		if row.permissionID == "" || !permissionCovers(snap, row.permissionID, operation) || !row.scope.matches(resource) {
			continue
		}
		if !rowActive(row.effectiveFrom, row.effectiveTo, at) {
			continue
		}
		candidates = append(candidates, candidate{
			permission: row.permissionID,
			scope:      row.scope,
			from:       row.effectiveFrom,
			to:         row.effectiveTo,
		})
	}
	sort.SliceStable(candidates, func(i, j int) bool { return candidateLess(candidates[i], candidates[j]) })
	return granted(candidates[0])
}

func granted(c candidate) *Decision {
	return &Decision{
		Granted: true,
		Match: &Match{
			Role:       c.role,
			Permission: c.permission,
			Scope:      c.scope.text,
		},
	}
}

func denied(reason string) *Decision {
	return &Decision{Granted: false, Reason: reason}
}
EOF
