	for _, parent := range in.Parents {
		if !validIdentifier(parent) {
			return invalidRequest("parents", "parents must contain parseable identifiers")
		}
		if seen[parent] {
			return invalidRequest("parents", "parent listed more than once")
		}
		seen[parent] = true
	}
