		return s.GrantBinding(LayerWrite{Subject: "user-1", Role: "viewer", OccurredAt: occurred, EffectiveFrom: from})
	}))
	if decide("2026-02-01T00:00:00Z").Reason != ReasonNoPermissionBinding {
